package controlpb

import (
	"testing"

	"google.golang.org/protobuf/proto"
)

// covMessage is every generated message: a proto.Message that also has the
// String(), Reset(), ProtoMessage() and Descriptor() methods generated by
// protoc-gen-go.
type covMessage interface {
	proto.Message
	String() string
	Reset()
	ProtoMessage()
	Descriptor() ([]byte, []int)
}

// roundTrip marshals m, unmarshals into a fresh value of the same type, and
// asserts proto.Equal. It also exercises String() and Reset() on the message.
func roundTrip[T covMessage](t *testing.T, m T, fresh T) {
	t.Helper()
	_ = m.ProtoReflect()
	m.ProtoMessage()
	if d, _ := m.Descriptor(); len(d) == 0 {
		t.Fatalf("empty descriptor")
	}
	s := proto.MessageName(m)
	if s == "" {
		t.Fatalf("empty message name")
	}
	b, err := proto.Marshal(m)
	if err != nil {
		t.Fatalf("marshal %s: %v", s, err)
	}
	if err := proto.Unmarshal(b, fresh); err != nil {
		t.Fatalf("unmarshal %s: %v", s, err)
	}
	if !proto.Equal(m, fresh) {
		t.Fatalf("round trip mismatch for %s:\n got %v\nwant %v", s, fresh, m)
	}
	_ = m.String()
	m.Reset()
}

func TestControlGenCoverage(t *testing.T) {
	node := &Node{
		Id:     "n1",
		Module: "mod",
		Params: []byte(`{"k":"v"}`),
		Env:    map[string]string{"E": "1"},
	}
	if node.GetId() != "n1" || node.GetModule() != "mod" || string(node.GetParams()) != `{"k":"v"}` || node.GetEnv()["E"] != "1" {
		t.Fatal("Node getters")
	}

	edge := &Edge{From: "a", FromPort: "out", To: "b", ToPort: "in", OnError: "skip"}
	if edge.GetFrom() != "a" || edge.GetFromPort() != "out" || edge.GetTo() != "b" || edge.GetToPort() != "in" || edge.GetOnError() != "skip" {
		t.Fatal("Edge getters")
	}

	trig := &GraphTrigger{Type: "cron", Cron: "* * * * *", Secret: "s", IntervalSeconds: 30}
	if trig.GetType() != "cron" || trig.GetCron() != "* * * * *" || trig.GetSecret() != "s" || trig.GetIntervalSeconds() != 30 {
		t.Fatal("GraphTrigger getters")
	}

	graph := &Graph{
		Id:        "g1",
		Version:   "v1",
		Tenant:    "t",
		Workspace: "w",
		Nodes:     []*Node{node},
		Edges:     []*Edge{edge},
		Triggers:  []*GraphTrigger{trig},
	}
	if graph.GetId() != "g1" || graph.GetVersion() != "v1" || graph.GetTenant() != "t" || graph.GetWorkspace() != "w" {
		t.Fatal("Graph scalar getters")
	}
	if len(graph.GetNodes()) != 1 || len(graph.GetEdges()) != 1 || len(graph.GetTriggers()) != 1 {
		t.Fatal("Graph repeated getters")
	}

	prog := &GraphProgress{JobId: "j", NodeId: "n", Percent: 42.5, Message: "msg"}
	if prog.GetJobId() != "j" || prog.GetNodeId() != "n" || prog.GetPercent() != 42.5 || prog.GetMessage() != "msg" {
		t.Fatal("GraphProgress getters")
	}

	jobErr := &JobError{Code: "E1", Message: "boom"}
	if jobErr.GetCode() != "E1" || jobErr.GetMessage() != "boom" {
		t.Fatal("JobError getters")
	}

	nodeRes := &NodeResult{NodeId: "n", Status: "ok", Error: jobErr}
	if nodeRes.GetNodeId() != "n" || nodeRes.GetStatus() != "ok" || nodeRes.GetError().GetCode() != "E1" {
		t.Fatal("NodeResult getters")
	}

	graphRes := &GraphResult{GraphId: "g1", Status: "ok", Nodes: []*NodeResult{nodeRes}, Error: jobErr}
	if graphRes.GetGraphId() != "g1" || graphRes.GetStatus() != "ok" || len(graphRes.GetNodes()) != 1 || graphRes.GetError() == nil {
		t.Fatal("GraphResult getters")
	}

	port := &Port{Id: "p", Mime: []string{"text/plain"}, Label: "L", Required: true, Variadic: true, Min: 1, Max: 5}
	if port.GetId() != "p" || len(port.GetMime()) != 1 || port.GetLabel() != "L" || !port.GetRequired() || !port.GetVariadic() || port.GetMin() != 1 || port.GetMax() != 5 {
		t.Fatal("Port getters")
	}

	man := &Manifest{
		Id:             "m",
		Version:        "v",
		Label:          "L",
		Color:          "#fff",
		ExecutionModel: "sync",
		ProcessModel:   "single",
		Inputs:         []*Port{port},
		Outputs:        []*Port{port},
		Idempotent:     true,
		RetryPolicy:    "none",
		Category:       "cat",
		Provider:       "prov",
		Tags:           []string{"t1"},
		Description:    "desc",
	}
	if man.GetId() != "m" || man.GetVersion() != "v" || man.GetLabel() != "L" || man.GetColor() != "#fff" ||
		man.GetExecutionModel() != "sync" || man.GetProcessModel() != "single" || len(man.GetInputs()) != 1 ||
		len(man.GetOutputs()) != 1 || !man.GetIdempotent() || man.GetRetryPolicy() != "none" ||
		man.GetCategory() != "cat" || man.GetProvider() != "prov" || len(man.GetTags()) != 1 || man.GetDescription() != "desc" {
		t.Fatal("Manifest getters")
	}

	jobRec := &JobRecord{
		Id: "id", GraphId: "g", NodeId: "n", Tenant: "t", Workspace: "w", Status: "running",
		EnqueuedAt: 1, StartedAt: 2, FinishedAt: 3, Attempt: 4, WorkerId: "wk", Error: jobErr,
	}
	if jobRec.GetId() != "id" || jobRec.GetGraphId() != "g" || jobRec.GetNodeId() != "n" || jobRec.GetTenant() != "t" ||
		jobRec.GetWorkspace() != "w" || jobRec.GetStatus() != "running" || jobRec.GetEnqueuedAt() != 1 ||
		jobRec.GetStartedAt() != 2 || jobRec.GetFinishedAt() != 3 || jobRec.GetAttempt() != 4 ||
		jobRec.GetWorkerId() != "wk" || jobRec.GetError() == nil {
		t.Fatal("JobRecord getters")
	}

	saveReq := &SaveGraphRequest{Graph: graph}
	if saveReq.GetGraph() == nil {
		t.Fatal("SaveGraphRequest getter")
	}
	saveResp := &SaveGraphResponse{Commit: "abc"}
	if saveResp.GetCommit() != "abc" {
		t.Fatal("SaveGraphResponse getter")
	}

	loadReq := &LoadGraphRequest{Tenant: "t", Workspace: "w", GraphId: "g", Ref: "HEAD"}
	if loadReq.GetTenant() != "t" || loadReq.GetWorkspace() != "w" || loadReq.GetGraphId() != "g" || loadReq.GetRef() != "HEAD" {
		t.Fatal("LoadGraphRequest getters")
	}
	loadResp := &LoadGraphResponse{Graph: graph}
	if loadResp.GetGraph() == nil {
		t.Fatal("LoadGraphResponse getter")
	}

	listReq := &ListGraphsRequest{Tenant: "t", Workspace: "w"}
	if listReq.GetTenant() != "t" || listReq.GetWorkspace() != "w" {
		t.Fatal("ListGraphsRequest getters")
	}
	listResp := &ListGraphsResponse{GraphIds: []string{"g1", "g2"}}
	if len(listResp.GetGraphIds()) != 2 {
		t.Fatal("ListGraphsResponse getter")
	}

	promReq := &PromoteGraphRequest{Tenant: "t", Workspace: "w", GraphId: "g", Env: "prod", Commit: "c"}
	if promReq.GetTenant() != "t" || promReq.GetWorkspace() != "w" || promReq.GetGraphId() != "g" || promReq.GetEnv() != "prod" || promReq.GetCommit() != "c" {
		t.Fatal("PromoteGraphRequest getters")
	}
	promResp := &PromoteGraphResponse{}

	runReq := &RunGraphRequest{Graph: graph, Tenant: "t", Workspace: "w", GraphId: "g", Ref: "r"}
	if runReq.GetGraph() == nil || runReq.GetTenant() != "t" || runReq.GetWorkspace() != "w" || runReq.GetGraphId() != "g" || runReq.GetRef() != "r" {
		t.Fatal("RunGraphRequest getters")
	}

	runCompleted := &RunGraphCompleted{JobId: "j", Result: graphRes}
	if runCompleted.GetJobId() != "j" || runCompleted.GetResult() == nil {
		t.Fatal("RunGraphCompleted getters")
	}

	// oneof variant 1: progress
	evProg := &RunGraphEvent{Payload: &RunGraphEvent_Progress{Progress: prog}}
	if evProg.GetPayload() == nil || evProg.GetProgress() == nil || evProg.GetCompleted() != nil {
		t.Fatal("RunGraphEvent progress oneof")
	}
	// oneof variant 2: completed
	evDone := &RunGraphEvent{Payload: &RunGraphEvent_Completed{Completed: runCompleted}}
	if evDone.GetPayload() == nil || evDone.GetCompleted() == nil || evDone.GetProgress() != nil {
		t.Fatal("RunGraphEvent completed oneof")
	}

	getJobReq := &GetJobRequest{JobId: "j"}
	if getJobReq.GetJobId() != "j" {
		t.Fatal("GetJobRequest getter")
	}
	listJobsForGraph := &ListJobsForGraphRequest{GraphId: "g"}
	if listJobsForGraph.GetGraphId() != "g" {
		t.Fatal("ListJobsForGraphRequest getter")
	}
	listJobsResp := &ListJobsResponse{Jobs: []*JobRecord{jobRec}}
	if len(listJobsResp.GetJobs()) != 1 {
		t.Fatal("ListJobsResponse getter")
	}

	cancelReq := &CancelJobRequest{JobId: "j", Reason: "stop"}
	if cancelReq.GetJobId() != "j" || cancelReq.GetReason() != "stop" {
		t.Fatal("CancelJobRequest getters")
	}
	cancelResp := &CancelJobResponse{}

	streamReq := &StreamJobLogsRequest{JobId: "j", Follow: true, AfterSeq: 7}
	if streamReq.GetJobId() != "j" || !streamReq.GetFollow() || streamReq.GetAfterSeq() != 7 {
		t.Fatal("StreamJobLogsRequest getters")
	}

	logEntry := &JobLogEntry{Seq: 1, Ts: "2026-06-26T00:00:00Z", NodeId: "n", Kind: "status", Message: "m", Stream: "stdout"}
	if logEntry.GetSeq() != 1 || logEntry.GetTs() == "" || logEntry.GetNodeId() != "n" || logEntry.GetKind() != "status" || logEntry.GetMessage() != "m" || logEntry.GetStream() != "stdout" {
		t.Fatal("JobLogEntry getters")
	}

	listDropsReq := &ListDropsRequest{Query: "q", Categories: []string{"c"}, Providers: []string{"p"}, Tags: []string{"t"}}
	if listDropsReq.GetQuery() != "q" || len(listDropsReq.GetCategories()) != 1 || len(listDropsReq.GetProviders()) != 1 || len(listDropsReq.GetTags()) != 1 {
		t.Fatal("ListDropsRequest getters")
	}
	listDropsResp := &ListDropsResponse{Drops: []*Manifest{man}}
	if len(listDropsResp.GetDrops()) != 1 {
		t.Fatal("ListDropsResponse getter")
	}

	// round-trip every message type
	roundTrip(t, node, &Node{})
	roundTrip(t, edge, &Edge{})
	roundTrip(t, graph, &Graph{})
	roundTrip(t, trig, &GraphTrigger{})
	roundTrip(t, prog, &GraphProgress{})
	roundTrip(t, jobErr, &JobError{})
	roundTrip(t, nodeRes, &NodeResult{})
	roundTrip(t, graphRes, &GraphResult{})
	roundTrip(t, port, &Port{})
	roundTrip(t, man, &Manifest{})
	roundTrip(t, jobRec, &JobRecord{})
	roundTrip(t, saveReq, &SaveGraphRequest{})
	roundTrip(t, saveResp, &SaveGraphResponse{})
	roundTrip(t, loadReq, &LoadGraphRequest{})
	roundTrip(t, loadResp, &LoadGraphResponse{})
	roundTrip(t, listReq, &ListGraphsRequest{})
	roundTrip(t, listResp, &ListGraphsResponse{})
	roundTrip(t, promReq, &PromoteGraphRequest{})
	roundTrip(t, promResp, &PromoteGraphResponse{})
	roundTrip(t, runReq, &RunGraphRequest{})
	roundTrip(t, runCompleted, &RunGraphCompleted{})
	roundTrip(t, evProg, &RunGraphEvent{})
	roundTrip(t, evDone, &RunGraphEvent{})
	roundTrip(t, getJobReq, &GetJobRequest{})
	roundTrip(t, listJobsForGraph, &ListJobsForGraphRequest{})
	roundTrip(t, listJobsResp, &ListJobsResponse{})
	roundTrip(t, cancelReq, &CancelJobRequest{})
	roundTrip(t, cancelResp, &CancelJobResponse{})
	roundTrip(t, streamReq, &StreamJobLogsRequest{})
	roundTrip(t, logEntry, &JobLogEntry{})
	roundTrip(t, listDropsReq, &ListDropsRequest{})
	roundTrip(t, listDropsResp, &ListDropsResponse{})
}

// TestControlNilGetters exercises getters on nil/zero receivers, which take the
// nil-guard branches in the generated code.
func TestControlNilGetters(t *testing.T) {
	var n *Node
	_ = n.GetId()
	_ = n.GetEnv()
	var g *Graph
	_ = g.GetNodes()
	var ev *RunGraphEvent
	_ = ev.GetPayload()
	_ = ev.GetProgress()
	_ = ev.GetCompleted()
	var nr *NodeResult
	_ = nr.GetError()
}
